"""Load an INI settings file into a dict."""

import configparser
import json
import sys

from schema import SCHEMA


def convert_value(value, type_):
    if type_ is bool:
        # handle true/false, yes/no, on/off, 1/0 case-insensitive
        lower = value.lower()
        if lower in {"true", "yes", "on", "1"}:
            return True
        if lower in {"false", "no", "off", "0"}:
            return False
        raise ValueError(f"Invalid boolean value: {value}")
    elif type_ is int:
        return int(value)
    elif type_ is list:
        # split by comma, strip spaces, drop empty items
        items = [item.strip() for item in value.split(",")]
        return [item for item in items if item]
    elif type_ is str:
        return value
    else:
        raise ValueError(f"Unsupported type: {type_}")


def load(path, schema=SCHEMA):
    """Return {section: {key: value}} for the INI file at `path`."""
    parser = configparser.ConfigParser()
    parser.read(path, encoding="utf-8")
    result = {}
    for section in parser.sections():
        section_dict = {}
        section_schema = schema.get(section, {})
        for key, value in parser[section].items():
            if key in section_schema:
                try:
                    section_dict[key] = convert_value(value, section_schema[key])
                except ValueError:
                    raise
            else:
                section_dict[key] = value
        result[section] = section_dict
    return result


if __name__ == "__main__":
    print(json.dumps(load(sys.argv[1]), indent=2))
