def render(rows, align=None):
    """Return the Markdown table for `rows` (a list of dicts) as a string ending in a newline."""
    if not rows:
        return ""
    # Determine columns in order of first appearance across all rows
    columns = []
    seen = set()
    for row in rows:
        for key in row:
            if key not in seen:
                seen.add(key)
                columns.append(key)
    # Compute column widths
    widths = {}
    for col in columns:
        # Header width
        w = len(col)
        # Data widths
        for row in rows:
            val = row.get(col, "")
            # Escape pipes in value for width calculation
            display_val = str(val).replace("|", "\\|")
            w = max(w, len(display_val))
        widths[col] = w
    # Determine alignment for each column
    if align is None:
        align = {}
        for col in columns:
            # Check if all values are numbers
            all_numbers = True
            for row in rows:
                val = row.get(col, "")
                try:
                    float(val)
                except (ValueError, TypeError):
                    all_numbers = False
                    break
            align[col] = "right" if all_numbers else "left"
    # Build header row
    header_cells = []
    for col in columns:
        w = widths[col]
        header = col
