            cell = header + " " * (w - len(header))
        elif align[col] == "right":
            cell = " " * (w - len(header)) + header
        elif align[col] == "center":
            left_pad = (w - len(header)) // 2
            right_pad = w - len(header) - left_pad
            cell = " " * left_pad + header + " " * right_pad
        else:
            cell = header
        header_cells.append(cell)
    lines = ["| " + " | ".join(header_cells) + " |"]
    # Build separator row
    sep_cells = []
    for col in columns:
        w = widths[col]
        if align[col] == "left":
            sep = ":" + "-" * (w - 1)
        elif align[col] == "right":
            sep = "-" * (w - 1) + ":"
        elif align[col] == "center":
            sep = ":" + "-" * (w - 2) + ":" if w >= 2 else ":|"
        else:
            sep = "-" * w
        sep_cells.append(sep)
    lines.append("| " + " | ".join(sep_cells) + " |")
    # Build data rows
    for row in rows:
        cells = []
        for col in columns:
            w = widths[col]
            val = row.get(col, "")
            # Escape pipes in value
            display_val = str(val).replace("|", "\\|")
            # Pad according to alignment
